/* clap's bin_name: the file name of argv[0] ("yr", "yr.exe"), or NULL when
 * argv[0] names no file ("", "." or ".."). The completion scripts keep the
 * fixed name "yr". */
static const char *yx_cli_bin_name = YX_CLI_PROGRAM_NAME;
static char *yx_cli_bin_name_storage;

static void yx_cli_set_bin_name(const char *argv0)
{
    const char *at = argv0, *name = NULL;
    size_t name_length = 0;
    yx_cli_bin_name = NULL;
    if (!argv0) return;
#ifdef _WIN32
    /* A drive prefix ("C:yr.exe") is not part of the file name. */
    if (((at[0] >= 'A' && at[0] <= 'Z') || (at[0] >= 'a' && at[0] <= 'z')) &&
        at[1] == ':') at += 2;
#endif
    while (*at) {
        const char *end = at;
#ifdef _WIN32
        while (*end && *end != '/' && *end != '\\') ++end;
#else
        while (*end && *end != '/') ++end;
#endif
        /* Path::file_name skips empty and "." components. */
        if (end > at && !(end - at == 1 && at[0] == '.')) {
            name = at;
            name_length = (size_t)(end - at);
        }
        at = *end ? end + 1 : end;
    }
    if (!name || (name_length == 2 && name[0] == '.' && name[1] == '.'))
        return;
    yx_cli_bin_name_storage = (char *)malloc(name_length + 1);
    if (!yx_cli_bin_name_storage) {
        yx_cli_bin_name = YX_CLI_PROGRAM_NAME;
        return;
    }
    memcpy(yx_cli_bin_name_storage, name, name_length);
    yx_cli_bin_name_storage[name_length] = '\0';
    yx_cli_bin_name = yx_cli_bin_name_storage;
}

/* Copy help or usage text, naming the program as clap does at the start of
 * each usage line ("Usage: yr ..." and the indented "  yr ..." help line).
 * Without a bin_name the root usage shows the package name and subcommand
 * usage shows only the subcommand path. */
void yx_cli_usage_write(const char *text, size_t length, FILE *stream)
{
    size_t line = 0, copied = 0;
    while (line < length) {
        size_t name = SIZE_MAX;
        const char *newline;
        if (length - line >= 9 && memcmp(text + line, "Usage: yr", 9) == 0)
            name = line + 7;
        else if (length - line >= 4 && memcmp(text + line, "  yr", 4) == 0)
            name = line + 2;
        if (name != SIZE_MAX && (name + 2 == length ||
                                 text[name + 2] == ' ' ||
                                 text[name + 2] == '\n')) {
            bool subcommand = name + 3 < length && text[name + 2] == ' ' &&
                              text[name + 3] >= 'a' && text[name + 3] <= 'z';
            (void)fwrite(text + copied, 1, name - copied, stream);
            if (yx_cli_bin_name) {
                (void)fputs(yx_cli_bin_name, stream);
                copied = name + 2;
            } else if (subcommand) {
                copied = name + 3;
            } else {
                (void)fputs(YX_CLI_PACKAGE_NAME, stream);
                copied = name + 2;
            }
        }
        newline = (const char *)memchr(text + line, '\n', length - line);
        if (!newline) break;
        line = (size_t)(newline - text) + 1;
    }
    (void)fwrite(text + copied, 1, length - copied, stream);
}

void yx_cli_usage_fputs(const char *text, FILE *stream)
{
    yx_cli_usage_write(text, strlen(text), stream);
}

void yx_cli_usage_fprintf(FILE *stream, const char *format, ...)
{
    va_list arguments;
    char *text;
    int length;
    va_start(arguments, format);
    length = vsnprintf(NULL, 0, format, arguments);
    va_end(arguments);
    if (length < 0) return;
    text = (char *)malloc((size_t)length + 1);
    va_start(arguments, format);
    if (text) (void)vsnprintf(text, (size_t)length + 1, format, arguments);
    else (void)vfprintf(stream, format, arguments);
    va_end(arguments);
    if (!text) return;
    yx_cli_usage_write(text, (size_t)length, stream);
    free(text);
}

static void yx_cli_help(bool scan, bool long_help)
{
    yx_cli_usage_fputs(
        scan ? (long_help ? yx_cli_help_scan_long : yx_cli_help_scan_short)
             : (long_help ? yx_cli_help_top_long : yx_cli_help_top_short),
        stdout);
    if (scan && long_help) yx_cli_usage_fputs(yx_cli_help_scan_long_tail, stdout);
}

