static bool yx_cli_unsigned(const char *text, const char *option,
                            uint64_t maximum, uint64_t *value)
{
    uint64_t result = 0;
    const unsigned char *p = (const unsigned char *)text;
    const char *reason = NULL;
    if (!p || !*p) reason = "cannot parse integer from empty string";
    else if (*p == '+') ++p;
    if (!reason && !*p) reason = "invalid digit found in string";
    for (; !reason && *p; ++p) {
        unsigned digit;
        if (*p < '0' || *p > '9') {
            reason = "invalid digit found in string";
            break;
        }
        digit = (unsigned)(*p - '0');
        if (result > (maximum - digit) / 10) {
            reason = "number too large to fit in target type";
            break;
        }
        result = result * 10 + digit;
    }
    if (reason) {
        fprintf(stderr,
                "error: invalid value '%s' for '%s': %s\n\n"
                "For more information, try '--help'.\n",
                text ? text : "", option, reason);
        return false;
    }
    *value = result;
    return true;
}

static bool yx_cli_size(const char *text, const char *option,
                        size_t *value)
{
    uint64_t result;
    if (!yx_cli_unsigned(text, option, SIZE_MAX, &result)) return false;
    *value = (size_t)result;
    return true;
}

static bool yx_cli_u64(const char *text, const char *option, uint64_t *value)
{
    return yx_cli_unsigned(text, option, UINT64_MAX, value);
}

static void yx_cli_missing_value(const char *option, const char *values)
{
    fprintf(stderr,
            "error: a value is required for '%s' but none was supplied\n",
            option);
    if (values) fprintf(stderr, "  [possible values: %s]\n", values);
    fputs("\nFor more information, try '--help'.\n", stderr);
}

/* Clap rejects repeated scan options unless they explicitly append values
 * (for example --define, --include-dir, and --ignore-module). */
static int yx_cli_unique_scan_option(const char *arg)
{
    if (strcmp(arg, "-c") == 0 || strcmp(arg, "--count") == 0) return 0;
    if (strcmp(arg, "-C") == 0 || strcmp(arg, "--compiled-rules") == 0) return 1;
    if (strcmp(arg, "-n") == 0 || strcmp(arg, "--negate") == 0) return 2;
    if (strcmp(arg, "--scan-list") == 0) return 3;
    if (strcmp(arg, "--path-as-namespace") == 0) return 4;
    if (strcmp(arg, "--ignore-invalid-rules") == 0) return 5;
    if (strcmp(arg, "--no-mmap") == 0) return 6;
    if (strcmp(arg, "-z") == 0 || strcmp(arg, "--skip-larger") == 0 ||
        strncmp(arg, "--skip-larger=", 14) == 0 ||
        (arg[0] == '-' && arg[1] == 'z' && arg[2])) return 7;
    if (strcmp(arg, "-a") == 0 || strcmp(arg, "--timeout") == 0 ||
        strncmp(arg, "--timeout=", 10) == 0 ||
        (arg[0] == '-' && arg[1] == 'a' && arg[2])) return 8;
    if (strcmp(arg, "-p") == 0 || strcmp(arg, "--threads") == 0 ||
        strncmp(arg, "--threads=", 10) == 0 ||
        (arg[0] == '-' && arg[1] == 'p' && arg[2])) return 9;
    if (strcmp(arg, "-t") == 0 || strcmp(arg, "--tag") == 0 ||
        strncmp(arg, "--tag=", 6) == 0 ||
        (arg[0] == '-' && arg[1] == 't' && arg[2])) return 10;
    if (strcmp(arg, "-r") == 0 || strcmp(arg, "--recursive") == 0 ||
        strncmp(arg, "--recursive=", 12) == 0 ||
        strncmp(arg, "-r=", 3) == 0) return 11;
    if (strcmp(arg, "-s") == 0 || strcmp(arg, "--print-strings") == 0 ||
        strncmp(arg, "--print-strings=", 16) == 0 ||
        strncmp(arg, "-s=", 3) == 0) return 12;
    if (strcmp(arg, "-m") == 0 || strcmp(arg, "--print-meta") == 0) return 13;
    if (strcmp(arg, "-g") == 0 || strcmp(arg, "--print-tags") == 0) return 14;
    if (strcmp(arg, "-e") == 0 || strcmp(arg, "--print-namespace") == 0) return 15;
    if (strcmp(arg, "--relaxed-re-syntax") == 0) return 16;
    if (strcmp(arg, "--disable-console-logs") == 0) return 17;
    if (strcmp(arg, "-f") == 0 || strcmp(arg, "--fast-scan") == 0) return 18;
    if (strcmp(arg, "-o") == 0 || strcmp(arg, "--output-format") == 0 ||
        strncmp(arg, "--output-format=", 16) == 0 ||
        (arg[0] == '-' && arg[1] == 'o' && arg[2])) return 19;
    if (strcmp(arg, "--max-matches-per-pattern") == 0 ||
        strncmp(arg, "--max-matches-per-pattern=", 26) == 0) return 20;
    if (strcmp(arg, "--cpu-limit") == 0 ||
        strncmp(arg, "--cpu-limit=", 12) == 0) return 21;
    if (strcmp(arg, "--profiling") == 0) return 22;
    return -1;
}

